// A trivial node_modules package required by the bench entry SOLELY to arm the
// native compartment fast-path guard (Runtime::anyCompartmentActive_).
//
// Under IBEX_COMPARTMENTS=1 the module loader binds this package's Domain to a
// withholding compartment global via __exactSetCompartmentFor, and that call
// arms `anyCompartmentActive_` for the whole runtime (see
// patches/hermes/0005-native-compartment-refinements.patch). This package's
// bare `process` therefore resolves to `undefined` through its compartment
// Proxy. Without IBEX_COMPARTMENTS no compartment is bound and `process` is the
// real object.
//
// The bench reads `processWithheld` back to CONFIRM that the active arm really
// flipped the guard (rather than merely setting an env var): armed === true iff
// the compartment walk is live.
module.exports.processWithheld = (typeof process === "undefined");
